-- Reference/demo data exported from the project database.
-- COPY first targets temporary staging tables so this migration is safe on an existing development database.

CREATE TEMP TABLE seed_poi ON COMMIT DROP AS
SELECT * FROM public.poi WITH NO DATA;


SELECT id, name, context, geom_local, coordinate_status, status, data_version, created_at, updated_at
FROM seed_poi
ON CONFLICT (id) DO NOTHING;

DO $verify$
BEGIN
    IF EXISTS (
        SELECT id FROM seed_poi
        EXCEPT
        SELECT id FROM public.poi
    ) THEN
        RAISE EXCEPTION 'Failed to merge all seed rows into public.poi';
    END IF;
END
$verify$;

SELECT setval(
    pg_get_serial_sequence('public.poi', 'id'),
    COALESCE((SELECT max(id) FROM public.poi), 1),
    EXISTS (SELECT 1 FROM public.poi)
);

ANALYZE public.poi;
